-- =============================================================================
-- OpenPOS local database schema (SQLite 3.37+ / STRICT tables)
-- Migration: 0001_init
-- Canonical operational store. Electron main process is the only writer.
-- =============================================================================
-- Conventions:
--   * IDs: UUIDv7 text, generated by the application.
--   * Money totals: INTEGER whole rupiah.
--   * Unit costs / average costs: REAL rupiah with up to 4 decimals.
--   * Quantities: REAL base units with up to 3 decimals.
--   * Timestamps: ISO-8601 UTC text ending in Z.
--   * Business dates: YYYY-MM-DD in the store timezone.
--   * Booleans: INTEGER 0/1 with CHECK constraints.
-- =============================================================================

PRAGMA journal_mode = WAL;
PRAGMA foreign_keys = ON;
PRAGMA busy_timeout = 5000;
PRAGMA synchronous = NORMAL;

BEGIN IMMEDIATE;

-- -----------------------------------------------------------------------------
-- Migration bookkeeping
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS schema_migrations (
  version     INTEGER PRIMARY KEY,
  name        TEXT NOT NULL,
  applied_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  checksum    TEXT
) STRICT;

-- -----------------------------------------------------------------------------
-- Store and application settings
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS stores (
  id                 TEXT PRIMARY KEY,
  name               TEXT NOT NULL,
  legal_name         TEXT,
  address            TEXT,
  phone              TEXT,
  email              TEXT,
  npwp               TEXT,
  currency           TEXT NOT NULL DEFAULT 'IDR' CHECK (length(currency) = 3),
  timezone           TEXT NOT NULL DEFAULT 'Asia/Jakarta',
  tax_enabled        INTEGER NOT NULL DEFAULT 0 CHECK (tax_enabled IN (0,1)),
  tax_rate           REAL NOT NULL DEFAULT 11.0 CHECK (tax_rate >= 0 AND tax_rate <= 100),
  tax_inclusive      INTEGER NOT NULL DEFAULT 1 CHECK (tax_inclusive IN (0,1)),
  rounding_increment INTEGER NOT NULL DEFAULT 100 CHECK (rounding_increment >= 0),
  receipt_header     TEXT,
  receipt_footer     TEXT,
  logo_path          TEXT,
  is_active          INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0,1)),
  created_at         TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at         TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  deleted_at         TEXT
) STRICT;

CREATE TABLE IF NOT EXISTS app_settings (
  store_id    TEXT NOT NULL,
  key         TEXT NOT NULL,
  value_json  TEXT NOT NULL CHECK (json_valid(value_json)),
  scope       TEXT NOT NULL DEFAULT 'store' CHECK (scope IN ('device','store')),
  is_secret   INTEGER NOT NULL DEFAULT 0 CHECK (is_secret IN (0,1)),
  updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (store_id, key),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE
) STRICT;

-- -----------------------------------------------------------------------------
-- Users, roles, permissions, audit
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS roles (
  id          TEXT PRIMARY KEY,
  store_id    TEXT NOT NULL,
  name        TEXT NOT NULL,
  slug        TEXT NOT NULL,
  description TEXT,
  is_system   INTEGER NOT NULL DEFAULT 0 CHECK (is_system IN (0,1)),
  created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  UNIQUE (store_id, slug)
) STRICT;

CREATE TABLE IF NOT EXISTS permissions (
  key         TEXT PRIMARY KEY,
  group_name  TEXT NOT NULL,
  description TEXT
) STRICT;

CREATE TABLE IF NOT EXISTS role_permissions (
  store_id       TEXT NOT NULL,
  role_id        TEXT NOT NULL,
  permission_key TEXT NOT NULL,
  created_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (role_id, permission_key),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (role_id) REFERENCES roles(id) ON DELETE CASCADE,
  FOREIGN KEY (permission_key) REFERENCES permissions(key) ON DELETE CASCADE
) STRICT;

CREATE TABLE IF NOT EXISTS users (
  id              TEXT PRIMARY KEY,
  store_id        TEXT NOT NULL,
  name            TEXT NOT NULL,
  username        TEXT NOT NULL COLLATE NOCASE,
  pin_hash        TEXT NOT NULL,
  role_id         TEXT NOT NULL,
  phone           TEXT,
  email           TEXT,
  is_active       INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0,1)),
  must_change_pin INTEGER NOT NULL DEFAULT 0 CHECK (must_change_pin IN (0,1)),
  last_login_at   TEXT,
  created_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  deleted_at      TEXT,
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (role_id) REFERENCES roles(id) ON DELETE RESTRICT,
  UNIQUE (store_id, username)
) STRICT;

CREATE TABLE IF NOT EXISTS activity_logs (
  id            TEXT PRIMARY KEY,
  store_id      TEXT NOT NULL,
  user_id       TEXT,
  action        TEXT NOT NULL,
  entity_type   TEXT,
  entity_id     TEXT,
  before_json   TEXT CHECK (before_json IS NULL OR json_valid(before_json)),
  after_json    TEXT CHECK (after_json IS NULL OR json_valid(after_json)),
  reason        TEXT,
  metadata_json TEXT CHECK (metadata_json IS NULL OR json_valid(metadata_json)),
  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
) STRICT;

CREATE TABLE IF NOT EXISTS document_sequences (
  id          TEXT PRIMARY KEY,
  store_id    TEXT NOT NULL,
  doc_type    TEXT NOT NULL CHECK (doc_type IN (
                'sale','return','void','purchase','po',
                'credit_payment','supplier_payment','journal')),
  period_key  TEXT NOT NULL,
  prefix      TEXT NOT NULL,
  next_value  INTEGER NOT NULL DEFAULT 1 CHECK (next_value >= 1),
  padding     INTEGER NOT NULL DEFAULT 4 CHECK (padding BETWEEN 1 AND 10),
  updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  UNIQUE (store_id, doc_type, period_key, prefix)
) STRICT;

-- Device-specific printer profiles. Never synced to the cloud.
CREATE TABLE IF NOT EXISTS printers (
  id             TEXT PRIMARY KEY,
  store_id       TEXT NOT NULL,
  name           TEXT NOT NULL,
  connection     TEXT NOT NULL CHECK (connection IN ('usb','bluetooth','network','system')),
  address        TEXT,
  vendor_id      TEXT,
  product_id     TEXT,
  paper_width    INTEGER NOT NULL DEFAULT 58 CHECK (paper_width IN (58, 80)),
  chars_per_line INTEGER NOT NULL DEFAULT 32 CHECK (chars_per_line BETWEEN 20 AND 64),
  is_default     INTEGER NOT NULL DEFAULT 0 CHECK (is_default IN (0,1)),
  is_active      INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0,1)),
  created_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE
) STRICT;

-- -----------------------------------------------------------------------------
-- Catalog: categories, units, products, variants, units, barcodes
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS categories (
  id          TEXT PRIMARY KEY,
  store_id    TEXT NOT NULL,
  parent_id   TEXT,
  name        TEXT NOT NULL,
  sort_order  INTEGER NOT NULL DEFAULT 0,
  is_active   INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0,1)),
  created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  deleted_at  TEXT,
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (parent_id) REFERENCES categories(id) ON DELETE RESTRICT
) STRICT;

CREATE TABLE IF NOT EXISTS units (
  id            TEXT PRIMARY KEY,
  store_id      TEXT NOT NULL,
  code          TEXT NOT NULL,
  name          TEXT NOT NULL,
  allow_decimal INTEGER NOT NULL DEFAULT 0 CHECK (allow_decimal IN (0,1)),
  is_active     INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0,1)),
  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  UNIQUE (store_id, code)
) STRICT;

CREATE TABLE IF NOT EXISTS products (
  id               TEXT PRIMARY KEY,
  store_id         TEXT NOT NULL,
  sku              TEXT,
  name             TEXT NOT NULL,
  category_id      TEXT,
  base_unit_id     TEXT NOT NULL,
  brand            TEXT,
  description      TEXT,
  cost_price       REAL NOT NULL DEFAULT 0 CHECK (cost_price >= 0),
  retail_price     INTEGER NOT NULL DEFAULT 0 CHECK (retail_price >= 0),
  min_stock_qty    REAL NOT NULL DEFAULT 0 CHECK (min_stock_qty >= 0),
  track_stock      INTEGER NOT NULL DEFAULT 1 CHECK (track_stock IN (0,1)),
  track_expiry     INTEGER NOT NULL DEFAULT 0 CHECK (track_expiry IN (0,1)),
  shelf_life_days  INTEGER CHECK (shelf_life_days IS NULL OR shelf_life_days >= 0),
  is_taxable       INTEGER NOT NULL DEFAULT 0 CHECK (is_taxable IN (0,1)),
  tax_rate         REAL NOT NULL DEFAULT 0 CHECK (tax_rate >= 0 AND tax_rate <= 100),
  image_path       TEXT,
  is_active        INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0,1)),
  created_at       TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at       TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  deleted_at       TEXT,
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE RESTRICT,
  FOREIGN KEY (base_unit_id) REFERENCES units(id) ON DELETE RESTRICT
) STRICT;

CREATE TABLE IF NOT EXISTS product_variants (
  id            TEXT PRIMARY KEY,
  store_id      TEXT NOT NULL,
  product_id    TEXT NOT NULL,
  sku           TEXT,
  name          TEXT NOT NULL,
  attributes_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(attributes_json)),
  retail_price  INTEGER CHECK (retail_price IS NULL OR retail_price >= 0),
  cost_price    REAL CHECK (cost_price IS NULL OR cost_price >= 0),
  is_active     INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0,1)),
  sort_order    INTEGER NOT NULL DEFAULT 0,
  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  deleted_at    TEXT,
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE
) STRICT;

CREATE TABLE IF NOT EXISTS product_units (
  id                  TEXT PRIMARY KEY,
  store_id            TEXT NOT NULL,
  product_id          TEXT NOT NULL,
  unit_id             TEXT NOT NULL,
  parent_unit_id      TEXT,
  factor_to_parent    REAL CHECK (factor_to_parent IS NULL OR factor_to_parent > 0),
  factor_to_base      REAL NOT NULL CHECK (factor_to_base > 0),
  selling_price       INTEGER CHECK (selling_price IS NULL OR selling_price >= 0),
  is_base             INTEGER NOT NULL DEFAULT 0 CHECK (is_base IN (0,1)),
  is_default_sale     INTEGER NOT NULL DEFAULT 0 CHECK (is_default_sale IN (0,1)),
  is_default_purchase INTEGER NOT NULL DEFAULT 0 CHECK (is_default_purchase IN (0,1)),
  sort_order          INTEGER NOT NULL DEFAULT 0,
  created_at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE,
  FOREIGN KEY (unit_id) REFERENCES units(id) ON DELETE RESTRICT,
  FOREIGN KEY (parent_unit_id) REFERENCES product_units(id) ON DELETE SET NULL,
  UNIQUE (product_id, unit_id)
) STRICT;

CREATE TABLE IF NOT EXISTS product_barcodes (
  id         TEXT PRIMARY KEY,
  store_id   TEXT NOT NULL,
  product_id TEXT NOT NULL,
  variant_id TEXT,
  unit_id    TEXT,
  barcode    TEXT NOT NULL,
  is_primary INTEGER NOT NULL DEFAULT 0 CHECK (is_primary IN (0,1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE,
  FOREIGN KEY (variant_id) REFERENCES product_variants(id) ON DELETE CASCADE,
  FOREIGN KEY (unit_id) REFERENCES units(id) ON DELETE RESTRICT,
  UNIQUE (store_id, barcode)
) STRICT;

CREATE TABLE IF NOT EXISTS customer_groups (
  id                       TEXT PRIMARY KEY,
  store_id                 TEXT NOT NULL,
  name                     TEXT NOT NULL,
  price_tier               TEXT NOT NULL DEFAULT 'retail'
                             CHECK (price_tier IN ('retail','wholesale','member','custom')),
  default_discount_percent REAL NOT NULL DEFAULT 0
                             CHECK (default_discount_percent >= 0 AND default_discount_percent <= 100),
  is_default               INTEGER NOT NULL DEFAULT 0 CHECK (is_default IN (0,1)),
  created_at               TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at               TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  UNIQUE (store_id, name)
) STRICT;

CREATE TABLE IF NOT EXISTS price_rules (
  id                    TEXT PRIMARY KEY,
  store_id              TEXT NOT NULL,
  name                  TEXT NOT NULL,
  scope                 TEXT NOT NULL CHECK (scope IN ('product','variant','category')),
  product_id            TEXT,
  variant_id            TEXT,
  category_id           TEXT,
  customer_id           TEXT,
  customer_group_id     TEXT,
  unit_id               TEXT,
  min_qty               REAL NOT NULL DEFAULT 1 CHECK (min_qty > 0),
  price                 INTEGER CHECK (price IS NULL OR price >= 0),
  discount_percent      REAL CHECK (discount_percent IS NULL OR
                                    (discount_percent >= 0 AND discount_percent <= 100)),
  priority              INTEGER NOT NULL DEFAULT 0,
  starts_at             TEXT,
  ends_at               TEXT,
  is_active             INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0,1)),
  created_at            TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at            TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE,
  FOREIGN KEY (variant_id) REFERENCES product_variants(id) ON DELETE CASCADE,
  FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE CASCADE,
  FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE CASCADE,
  FOREIGN KEY (customer_group_id) REFERENCES customer_groups(id) ON DELETE CASCADE,
  FOREIGN KEY (unit_id) REFERENCES units(id) ON DELETE RESTRICT,
  CHECK ((product_id IS NOT NULL) + (variant_id IS NOT NULL) + (category_id IS NOT NULL) = 1),
  CHECK ((price IS NOT NULL) + (discount_percent IS NOT NULL) = 1)
) STRICT;

CREATE TABLE IF NOT EXISTS product_suppliers (
  id               TEXT PRIMARY KEY,
  store_id         TEXT NOT NULL,
  product_id       TEXT NOT NULL,
  variant_id       TEXT,
  supplier_id      TEXT NOT NULL,
  supplier_sku     TEXT,
  last_cost        REAL CHECK (last_cost IS NULL OR last_cost >= 0),
  last_purchase_at TEXT,
  is_preferred     INTEGER NOT NULL DEFAULT 0 CHECK (is_preferred IN (0,1)),
  created_at       TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at       TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE,
  FOREIGN KEY (variant_id) REFERENCES product_variants(id) ON DELETE CASCADE,
  FOREIGN KEY (supplier_id) REFERENCES suppliers(id) ON DELETE CASCADE
) STRICT;

-- -----------------------------------------------------------------------------
-- Inventory
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS stock_levels (
  id           TEXT PRIMARY KEY,
  store_id     TEXT NOT NULL,
  product_id   TEXT NOT NULL,
  variant_id   TEXT,
  qty_on_hand  REAL NOT NULL DEFAULT 0,
  qty_reserved REAL NOT NULL DEFAULT 0,
  avg_cost     REAL NOT NULL DEFAULT 0 CHECK (avg_cost >= 0),
  last_cost    REAL NOT NULL DEFAULT 0 CHECK (last_cost >= 0),
  updated_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE,
  FOREIGN KEY (variant_id) REFERENCES product_variants(id) ON DELETE CASCADE,
  UNIQUE (store_id, product_id, variant_id)
) STRICT;

CREATE TABLE IF NOT EXISTS stock_batches (
  id               TEXT PRIMARY KEY,
  store_id         TEXT NOT NULL,
  product_id       TEXT NOT NULL,
  variant_id       TEXT,
  purchase_item_id TEXT,
  batch_no         TEXT,
  expiry_date      TEXT,
  qty_received     REAL NOT NULL DEFAULT 0 CHECK (qty_received >= 0),
  qty_remaining    REAL NOT NULL DEFAULT 0 CHECK (qty_remaining >= 0),
  unit_cost        REAL NOT NULL DEFAULT 0 CHECK (unit_cost >= 0),
  received_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  created_at       TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE,
  FOREIGN KEY (variant_id) REFERENCES product_variants(id) ON DELETE CASCADE,
  FOREIGN KEY (purchase_item_id) REFERENCES purchase_items(id) ON DELETE SET NULL
) STRICT;

CREATE TABLE IF NOT EXISTS stock_movements (
  id                TEXT PRIMARY KEY,
  store_id          TEXT NOT NULL,
  product_id        TEXT NOT NULL,
  variant_id        TEXT,
  batch_id          TEXT,
  movement_type     TEXT NOT NULL CHECK (movement_type IN (
                      'opening','purchase','purchase_return','sale','sale_return',
                      'adjustment','opname','waste','expiry','transfer_in','transfer_out')),
  qty_delta         REAL NOT NULL CHECK (qty_delta != 0),
  qty_input         REAL,
  unit_id           TEXT,
  conversion_factor REAL NOT NULL DEFAULT 1 CHECK (conversion_factor > 0),
  unit_cost         REAL NOT NULL DEFAULT 0 CHECK (unit_cost >= 0),
  total_cost        INTEGER NOT NULL DEFAULT 0,
  reference_type    TEXT,
  reference_id      TEXT,
  reason            TEXT,
  note              TEXT,
  business_date     TEXT NOT NULL,
  user_id           TEXT,
  created_at        TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE,
  FOREIGN KEY (variant_id) REFERENCES product_variants(id) ON DELETE CASCADE,
  FOREIGN KEY (batch_id) REFERENCES stock_batches(id) ON DELETE RESTRICT,
  FOREIGN KEY (unit_id) REFERENCES units(id) ON DELETE RESTRICT,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
) STRICT;

CREATE TABLE IF NOT EXISTS stock_opname_sessions (
  id           TEXT PRIMARY KEY,
  store_id     TEXT NOT NULL,
  name         TEXT NOT NULL,
  scope_json   TEXT NOT NULL DEFAULT '{"type":"all"}' CHECK (json_valid(scope_json)),
  status       TEXT NOT NULL DEFAULT 'draft'
                 CHECK (status IN ('draft','counting','finalized','cancelled')),
  started_by   TEXT NOT NULL,
  started_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  finalized_by TEXT,
  finalized_at TEXT,
  notes        TEXT,
  created_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (started_by) REFERENCES users(id) ON DELETE RESTRICT,
  FOREIGN KEY (finalized_by) REFERENCES users(id) ON DELETE RESTRICT
) STRICT;

CREATE TABLE IF NOT EXISTS stock_opname_items (
  id             TEXT PRIMARY KEY,
  store_id       TEXT NOT NULL,
  session_id     TEXT NOT NULL,
  product_id     TEXT NOT NULL,
  variant_id     TEXT,
  system_qty     REAL NOT NULL DEFAULT 0,
  counted_qty    REAL CHECK (counted_qty IS NULL OR counted_qty >= 0),
  difference_qty REAL,
  unit_cost      REAL NOT NULL DEFAULT 0 CHECK (unit_cost >= 0),
  reason         TEXT,
  created_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (session_id) REFERENCES stock_opname_sessions(id) ON DELETE CASCADE,
  FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE,
  FOREIGN KEY (variant_id) REFERENCES product_variants(id) ON DELETE CASCADE
) STRICT;

-- -----------------------------------------------------------------------------
-- Customers and credit
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS customers (
  id               TEXT PRIMARY KEY,
  store_id         TEXT NOT NULL,
  name             TEXT NOT NULL,
  phone            TEXT,
  phone_normalized TEXT,
  email            TEXT,
  address          TEXT,
  customer_group_id TEXT,
  credit_limit     INTEGER NOT NULL DEFAULT 0 CHECK (credit_limit >= 0),
  credit_term_days INTEGER NOT NULL DEFAULT 30 CHECK (credit_term_days >= 0),
  credit_balance   INTEGER NOT NULL DEFAULT 0,
  notes            TEXT,
  is_active        INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0,1)),
  created_at       TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at       TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  deleted_at       TEXT,
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (customer_group_id) REFERENCES customer_groups(id) ON DELETE SET NULL
) STRICT;

CREATE TABLE IF NOT EXISTS credit_ledger (
  id             TEXT PRIMARY KEY,
  store_id       TEXT NOT NULL,
  customer_id    TEXT NOT NULL,
  entry_type     TEXT NOT NULL CHECK (entry_type IN (
                   'opening','charge','payment','adjustment','write_off','return_credit','void')),
  amount         INTEGER NOT NULL CHECK (amount != 0),
  balance_after  INTEGER NOT NULL,
  sale_id        TEXT,
  due_date       TEXT,
  reference_type TEXT,
  reference_id   TEXT,
  note           TEXT,
  created_by     TEXT,
  created_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE RESTRICT,
  FOREIGN KEY (sale_id) REFERENCES sales(id) ON DELETE RESTRICT,
  FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL
) STRICT;

CREATE TABLE IF NOT EXISTS credit_payments (
  id            TEXT PRIMARY KEY,
  store_id      TEXT NOT NULL,
  customer_id   TEXT NOT NULL,
  shift_id      TEXT,
  amount        INTEGER NOT NULL CHECK (amount > 0),
  method        TEXT NOT NULL CHECK (method IN ('cash','bank_transfer','ewallet','qris','other')),
  reference_no  TEXT,
  note          TEXT,
  paid_at       TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  received_by   TEXT NOT NULL,
  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  voided_at     TEXT,
  void_reason   TEXT,
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE RESTRICT,
  FOREIGN KEY (shift_id) REFERENCES shifts(id) ON DELETE RESTRICT,
  FOREIGN KEY (received_by) REFERENCES users(id) ON DELETE RESTRICT
) STRICT;

-- -----------------------------------------------------------------------------
-- Suppliers and purchasing
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS suppliers (
  id                TEXT PRIMARY KEY,
  store_id          TEXT NOT NULL,
  name              TEXT NOT NULL,
  code              TEXT,
  contact_name      TEXT,
  phone             TEXT,
  email             TEXT,
  address           TEXT,
  payment_term_days INTEGER NOT NULL DEFAULT 0 CHECK (payment_term_days >= 0),
  notes             TEXT,
  is_active         INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0,1)),
  created_at        TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at        TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  deleted_at        TEXT,
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE
) STRICT;

CREATE TABLE IF NOT EXISTS purchase_orders (
  id             TEXT PRIMARY KEY,
  store_id       TEXT NOT NULL,
  po_no          TEXT NOT NULL,
  supplier_id    TEXT NOT NULL,
  status         TEXT NOT NULL DEFAULT 'draft'
                   CHECK (status IN ('draft','ordered','partially_received','received','cancelled')),
  order_date     TEXT NOT NULL,
  expected_date  TEXT,
  subtotal       INTEGER NOT NULL DEFAULT 0 CHECK (subtotal >= 0),
  discount_total INTEGER NOT NULL DEFAULT 0 CHECK (discount_total >= 0),
  tax_total      INTEGER NOT NULL DEFAULT 0 CHECK (tax_total >= 0),
  grand_total    INTEGER NOT NULL DEFAULT 0 CHECK (grand_total >= 0),
  notes          TEXT,
  created_by     TEXT NOT NULL,
  approved_by    TEXT,
  created_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (supplier_id) REFERENCES suppliers(id) ON DELETE RESTRICT,
  FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE RESTRICT,
  FOREIGN KEY (approved_by) REFERENCES users(id) ON DELETE RESTRICT,
  UNIQUE (store_id, po_no)
) STRICT;

CREATE TABLE IF NOT EXISTS purchase_order_items (
  id                TEXT PRIMARY KEY,
  store_id          TEXT NOT NULL,
  purchase_order_id TEXT NOT NULL,
  product_id        TEXT NOT NULL,
  variant_id        TEXT,
  unit_id           TEXT NOT NULL,
  qty               REAL NOT NULL CHECK (qty > 0),
  conversion_factor REAL NOT NULL CHECK (conversion_factor > 0),
  unit_cost         INTEGER NOT NULL DEFAULT 0 CHECK (unit_cost >= 0),
  line_total        INTEGER NOT NULL DEFAULT 0 CHECK (line_total >= 0),
  qty_received      REAL NOT NULL DEFAULT 0 CHECK (qty_received >= 0),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (purchase_order_id) REFERENCES purchase_orders(id) ON DELETE CASCADE,
  FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE RESTRICT,
  FOREIGN KEY (variant_id) REFERENCES product_variants(id) ON DELETE RESTRICT,
  FOREIGN KEY (unit_id) REFERENCES units(id) ON DELETE RESTRICT
) STRICT;

CREATE TABLE IF NOT EXISTS purchases (
  id                  TEXT PRIMARY KEY,
  store_id            TEXT NOT NULL,
  purchase_no         TEXT NOT NULL,
  supplier_invoice_no TEXT,
  purchase_order_id   TEXT,
  supplier_id         TEXT NOT NULL,
  status              TEXT NOT NULL DEFAULT 'draft'
                        CHECK (status IN ('draft','posted','voided')),
  invoice_date        TEXT NOT NULL,
  due_date            TEXT,
  subtotal            INTEGER NOT NULL DEFAULT 0 CHECK (subtotal >= 0),
  discount_total      INTEGER NOT NULL DEFAULT 0 CHECK (discount_total >= 0),
  tax_total           INTEGER NOT NULL DEFAULT 0 CHECK (tax_total >= 0),
  shipping_total      INTEGER NOT NULL DEFAULT 0 CHECK (shipping_total >= 0),
  grand_total         INTEGER NOT NULL DEFAULT 0 CHECK (grand_total >= 0),
  paid_total          INTEGER NOT NULL DEFAULT 0 CHECK (paid_total >= 0),
  due_total           INTEGER NOT NULL DEFAULT 0 CHECK (due_total >= 0),
  notes               TEXT,
  created_by          TEXT NOT NULL,
  posted_by           TEXT,
  posted_at           TEXT,
  created_at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (purchase_order_id) REFERENCES purchase_orders(id) ON DELETE SET NULL,
  FOREIGN KEY (supplier_id) REFERENCES suppliers(id) ON DELETE RESTRICT,
  FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE RESTRICT,
  FOREIGN KEY (posted_by) REFERENCES users(id) ON DELETE RESTRICT,
  UNIQUE (store_id, purchase_no)
) STRICT;

CREATE TABLE IF NOT EXISTS purchase_items (
  id                TEXT PRIMARY KEY,
  store_id          TEXT NOT NULL,
  purchase_id       TEXT NOT NULL,
  product_id        TEXT NOT NULL,
  variant_id        TEXT,
  unit_id           TEXT NOT NULL,
  qty               REAL NOT NULL CHECK (qty > 0),
  conversion_factor REAL NOT NULL CHECK (conversion_factor > 0),
  qty_base          REAL NOT NULL CHECK (qty_base > 0),
  unit_cost         INTEGER NOT NULL DEFAULT 0 CHECK (unit_cost >= 0),
  unit_cost_base    REAL NOT NULL DEFAULT 0 CHECK (unit_cost_base >= 0),
  discount_amount   INTEGER NOT NULL DEFAULT 0 CHECK (discount_amount >= 0),
  line_total        INTEGER NOT NULL DEFAULT 0 CHECK (line_total >= 0),
  expiry_date       TEXT,
  batch_no          TEXT,
  created_at        TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (purchase_id) REFERENCES purchases(id) ON DELETE CASCADE,
  FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE RESTRICT,
  FOREIGN KEY (variant_id) REFERENCES product_variants(id) ON DELETE RESTRICT,
  FOREIGN KEY (unit_id) REFERENCES units(id) ON DELETE RESTRICT
) STRICT;

CREATE TABLE IF NOT EXISTS supplier_payments (
  id           TEXT PRIMARY KEY,
  store_id     TEXT NOT NULL,
  supplier_id  TEXT NOT NULL,
  purchase_id  TEXT,
  shift_id     TEXT,
  amount       INTEGER NOT NULL CHECK (amount > 0),
  method       TEXT NOT NULL CHECK (method IN ('cash','bank_transfer','ewallet','other')),
  reference_no TEXT,
  note         TEXT,
  paid_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  status       TEXT NOT NULL DEFAULT 'posted' CHECK (status IN ('posted','voided')),
  created_by   TEXT NOT NULL,
  created_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  voided_at    TEXT,
  void_reason  TEXT,
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (supplier_id) REFERENCES suppliers(id) ON DELETE RESTRICT,
  FOREIGN KEY (purchase_id) REFERENCES purchases(id) ON DELETE SET NULL,
  FOREIGN KEY (shift_id) REFERENCES shifts(id) ON DELETE RESTRICT,
  FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE RESTRICT
) STRICT;

CREATE TABLE IF NOT EXISTS purchase_returns (
  id            TEXT PRIMARY KEY,
  store_id      TEXT NOT NULL,
  purchase_id   TEXT NOT NULL,
  supplier_id   TEXT NOT NULL,
  return_no     TEXT NOT NULL,
  business_date TEXT NOT NULL,
  reason        TEXT NOT NULL,
  total_amount  INTEGER NOT NULL DEFAULT 0 CHECK (total_amount >= 0),
  status        TEXT NOT NULL DEFAULT 'posted' CHECK (status IN ('posted','voided')),
  created_by    TEXT NOT NULL,
  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (purchase_id) REFERENCES purchases(id) ON DELETE RESTRICT,
  FOREIGN KEY (supplier_id) REFERENCES suppliers(id) ON DELETE RESTRICT,
  FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE RESTRICT,
  UNIQUE (store_id, return_no)
) STRICT;

CREATE TABLE IF NOT EXISTS purchase_return_items (
  id               TEXT PRIMARY KEY,
  store_id         TEXT NOT NULL,
  return_id        TEXT NOT NULL,
  purchase_item_id TEXT NOT NULL,
  product_id       TEXT NOT NULL,
  variant_id       TEXT,
  unit_id          TEXT NOT NULL,
  qty              REAL NOT NULL CHECK (qty > 0),
  qty_base         REAL NOT NULL CHECK (qty_base > 0),
  unit_cost        REAL NOT NULL DEFAULT 0 CHECK (unit_cost >= 0),
  line_total       INTEGER NOT NULL DEFAULT 0 CHECK (line_total >= 0),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (return_id) REFERENCES purchase_returns(id) ON DELETE CASCADE,
  FOREIGN KEY (purchase_item_id) REFERENCES purchase_items(id) ON DELETE RESTRICT,
  FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE RESTRICT,
  FOREIGN KEY (variant_id) REFERENCES product_variants(id) ON DELETE RESTRICT,
  FOREIGN KEY (unit_id) REFERENCES units(id) ON DELETE RESTRICT
) STRICT;

-- -----------------------------------------------------------------------------
-- Operating expenses
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS expense_categories (
  id         TEXT PRIMARY KEY,
  store_id   TEXT NOT NULL,
  name       TEXT NOT NULL,
  is_active  INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0,1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  UNIQUE (store_id, name)
) STRICT;

CREATE TABLE IF NOT EXISTS expenses (
  id            TEXT PRIMARY KEY,
  store_id      TEXT NOT NULL,
  shift_id      TEXT,
  category_id   TEXT NOT NULL,
  amount        INTEGER NOT NULL CHECK (amount > 0),
  paid_from     TEXT NOT NULL DEFAULT 'cash_drawer'
                  CHECK (paid_from IN ('cash_drawer','bank','ewallet','other')),
  description   TEXT NOT NULL,
  reference_no  TEXT,
  business_date TEXT NOT NULL,
  spent_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  created_by    TEXT NOT NULL,
  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  voided_at     TEXT,
  void_reason   TEXT,
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (shift_id) REFERENCES shifts(id) ON DELETE RESTRICT,
  FOREIGN KEY (category_id) REFERENCES expense_categories(id) ON DELETE RESTRICT,
  FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE RESTRICT
) STRICT;

-- -----------------------------------------------------------------------------
-- Accounting (double-entry general ledger)
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS accounts (
  id             TEXT PRIMARY KEY,
  store_id       TEXT NOT NULL,
  code           TEXT NOT NULL,
  name           TEXT NOT NULL,
  type           TEXT NOT NULL CHECK (type IN ('asset','liability','equity','revenue','expense')),
  normal_balance TEXT NOT NULL CHECK (normal_balance IN ('debit','credit')),
  parent_id      TEXT,
  is_system      INTEGER NOT NULL DEFAULT 0 CHECK (is_system IN (0,1)),
  is_active      INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0,1)),
  created_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (parent_id) REFERENCES accounts(id) ON DELETE RESTRICT,
  UNIQUE (store_id, code)
) STRICT;

CREATE TABLE IF NOT EXISTS account_mappings (
  id          TEXT PRIMARY KEY,
  store_id    TEXT NOT NULL,
  mapping_key TEXT NOT NULL,
  account_id  TEXT NOT NULL,
  created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE RESTRICT,
  UNIQUE (store_id, mapping_key)
) STRICT;

CREATE TABLE IF NOT EXISTS accounting_periods (
  id         TEXT PRIMARY KEY,
  store_id   TEXT NOT NULL,
  period_key TEXT NOT NULL,
  status     TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','closed')),
  closed_by  TEXT,
  closed_at  TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (closed_by) REFERENCES users(id) ON DELETE RESTRICT,
  UNIQUE (store_id, period_key)
) STRICT;

CREATE TABLE IF NOT EXISTS journal_entries (
  id            TEXT PRIMARY KEY,
  store_id      TEXT NOT NULL,
  entry_no      TEXT NOT NULL,
  entry_date    TEXT NOT NULL,
  period_key    TEXT NOT NULL,
  source_type   TEXT NOT NULL CHECK (source_type IN (
                  'sale','sale_return','sale_void','purchase','purchase_return',
                  'supplier_payment','credit_payment','expense','stock_adjustment',
                  'opname','shift_close','opening_balance','manual')),
  source_id     TEXT,
  description   TEXT,
  status        TEXT NOT NULL DEFAULT 'posted' CHECK (status IN ('posted','voided')),
  reversal_of_id TEXT,
  created_by    TEXT,
  posted_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  voided_at     TEXT,
  voided_by     TEXT,
  void_reason   TEXT,
  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (reversal_of_id) REFERENCES journal_entries(id) ON DELETE RESTRICT,
  FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL,
  FOREIGN KEY (voided_by) REFERENCES users(id) ON DELETE SET NULL,
  UNIQUE (store_id, entry_no),
  UNIQUE (store_id, source_type, source_id)
) STRICT;

CREATE TABLE IF NOT EXISTS journal_lines (
  id               TEXT PRIMARY KEY,
  store_id         TEXT NOT NULL,
  journal_entry_id TEXT NOT NULL,
  line_no          INTEGER NOT NULL CHECK (line_no > 0),
  account_id       TEXT NOT NULL,
  debit            INTEGER NOT NULL DEFAULT 0 CHECK (debit >= 0),
  credit           INTEGER NOT NULL DEFAULT 0 CHECK (credit >= 0),
  memo             TEXT,
  customer_id      TEXT,
  supplier_id      TEXT,
  created_at       TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (journal_entry_id) REFERENCES journal_entries(id) ON DELETE CASCADE,
  FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE RESTRICT,
  FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE SET NULL,
  FOREIGN KEY (supplier_id) REFERENCES suppliers(id) ON DELETE SET NULL,
  CHECK ((debit > 0 AND credit = 0) OR (credit > 0 AND debit = 0))
) STRICT;

-- -----------------------------------------------------------------------------
-- Shifts, cash drawer, sales
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS shifts (
  id            TEXT PRIMARY KEY,
  store_id      TEXT NOT NULL,
  register_name TEXT NOT NULL,
  device_id     TEXT NOT NULL,
  opened_by     TEXT NOT NULL,
  opened_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  opening_cash  INTEGER NOT NULL DEFAULT 0 CHECK (opening_cash >= 0),
  closed_by     TEXT,
  closed_at     TEXT,
  expected_cash INTEGER,
  counted_cash  INTEGER CHECK (counted_cash IS NULL OR counted_cash >= 0),
  difference    INTEGER,
  status        TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','closed','reconciled')),
  closing_note  TEXT,
  business_date TEXT NOT NULL,
  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (opened_by) REFERENCES users(id) ON DELETE RESTRICT,
  FOREIGN KEY (closed_by) REFERENCES users(id) ON DELETE RESTRICT
) STRICT;

CREATE TABLE IF NOT EXISTS cash_movements (
  id             TEXT PRIMARY KEY,
  store_id       TEXT NOT NULL,
  shift_id       TEXT NOT NULL,
  type           TEXT NOT NULL CHECK (type IN (
                   'sale','refund','credit_payment','supplier_payment','expense',
                   'cash_in','cash_out','adjustment')),
  amount         INTEGER NOT NULL CHECK (amount != 0),
  reference_type TEXT,
  reference_id   TEXT,
  note           TEXT,
  business_date  TEXT NOT NULL,
  user_id        TEXT NOT NULL,
  created_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (shift_id) REFERENCES shifts(id) ON DELETE RESTRICT,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE RESTRICT
) STRICT;

CREATE TABLE IF NOT EXISTS sales (
  id                  TEXT PRIMARY KEY,
  store_id            TEXT NOT NULL,
  shift_id            TEXT,
  receipt_no          TEXT,
  business_date       TEXT NOT NULL,
  customer_id         TEXT,
  cashier_id          TEXT NOT NULL,
  status              TEXT NOT NULL DEFAULT 'held'
                        CHECK (status IN ('held','completed','voided')),
  payment_status      TEXT NOT NULL DEFAULT 'unpaid'
                        CHECK (payment_status IN ('unpaid','partial','paid','refunded')),
  price_tier          TEXT NOT NULL DEFAULT 'retail'
                        CHECK (price_tier IN ('retail','wholesale','member','custom')),
  hold_label          TEXT,
  hold_note           TEXT,
  hold_expires_at     TEXT,
  subtotal            INTEGER NOT NULL DEFAULT 0 CHECK (subtotal >= 0),
  item_discount_total INTEGER NOT NULL DEFAULT 0 CHECK (item_discount_total >= 0),
  order_discount_total INTEGER NOT NULL DEFAULT 0 CHECK (order_discount_total >= 0),
  tax_total           INTEGER NOT NULL DEFAULT 0 CHECK (tax_total >= 0),
  rounding_total      INTEGER NOT NULL DEFAULT 0,
  grand_total         INTEGER NOT NULL DEFAULT 0 CHECK (grand_total >= 0),
  paid_total          INTEGER NOT NULL DEFAULT 0 CHECK (paid_total >= 0),
  change_total        INTEGER NOT NULL DEFAULT 0 CHECK (change_total >= 0),
  due_total           INTEGER NOT NULL DEFAULT 0 CHECK (due_total >= 0),
  cost_total          INTEGER NOT NULL DEFAULT 0 CHECK (cost_total >= 0),
  note                TEXT,
  held_at             TEXT,
  completed_at        TEXT,
  voided_at           TEXT,
  voided_by           TEXT,
  void_reason         TEXT,
  created_at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (shift_id) REFERENCES shifts(id) ON DELETE RESTRICT,
  FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE RESTRICT,
  FOREIGN KEY (cashier_id) REFERENCES users(id) ON DELETE RESTRICT,
  FOREIGN KEY (voided_by) REFERENCES users(id) ON DELETE RESTRICT,
  CHECK (paid_total <= grand_total),
  CHECK (paid_total + due_total <= grand_total)
) STRICT;

CREATE TABLE IF NOT EXISTS sale_items (
  id                TEXT PRIMARY KEY,
  store_id          TEXT NOT NULL,
  sale_id           TEXT NOT NULL,
  line_no           INTEGER NOT NULL CHECK (line_no > 0),
  product_id        TEXT NOT NULL,
  variant_id        TEXT,
  unit_id           TEXT NOT NULL,
  qty               REAL NOT NULL CHECK (qty > 0),
  conversion_factor REAL NOT NULL CHECK (conversion_factor > 0),
  qty_base          REAL NOT NULL CHECK (qty_base > 0),
  unit_price        INTEGER NOT NULL DEFAULT 0 CHECK (unit_price >= 0),
  price_source      TEXT NOT NULL DEFAULT 'product'
                      CHECK (price_source IN ('customer','group','wholesale','unit','variant','product','manual')),
  price_rule_id     TEXT,
  discount_percent  REAL NOT NULL DEFAULT 0 CHECK (discount_percent >= 0 AND discount_percent <= 100),
  discount_amount   INTEGER NOT NULL DEFAULT 0 CHECK (discount_amount >= 0),
  tax_rate          REAL NOT NULL DEFAULT 0 CHECK (tax_rate >= 0 AND tax_rate <= 100),
  tax_amount        INTEGER NOT NULL DEFAULT 0 CHECK (tax_amount >= 0),
  gross_amount      INTEGER NOT NULL DEFAULT 0 CHECK (gross_amount >= 0),
  line_total        INTEGER NOT NULL DEFAULT 0 CHECK (line_total >= 0),
  unit_cost_base    REAL NOT NULL DEFAULT 0 CHECK (unit_cost_base >= 0),
  cost_total        INTEGER NOT NULL DEFAULT 0 CHECK (cost_total >= 0),
  note              TEXT,
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (sale_id) REFERENCES sales(id) ON DELETE CASCADE,
  FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE RESTRICT,
  FOREIGN KEY (variant_id) REFERENCES product_variants(id) ON DELETE RESTRICT,
  FOREIGN KEY (unit_id) REFERENCES units(id) ON DELETE RESTRICT,
  FOREIGN KEY (price_rule_id) REFERENCES price_rules(id) ON DELETE SET NULL,
  UNIQUE (sale_id, line_no)
) STRICT;

CREATE TABLE IF NOT EXISTS sale_item_batches (
  id           TEXT PRIMARY KEY,
  store_id     TEXT NOT NULL,
  sale_item_id TEXT NOT NULL,
  batch_id     TEXT NOT NULL,
  qty_base     REAL NOT NULL CHECK (qty_base > 0),
  unit_cost    REAL NOT NULL DEFAULT 0 CHECK (unit_cost >= 0),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (sale_item_id) REFERENCES sale_items(id) ON DELETE CASCADE,
  FOREIGN KEY (batch_id) REFERENCES stock_batches(id) ON DELETE RESTRICT
) STRICT;

CREATE TABLE IF NOT EXISTS payments (
  id             TEXT PRIMARY KEY,
  store_id       TEXT NOT NULL,
  sale_id        TEXT NOT NULL,
  shift_id       TEXT,
  method         TEXT NOT NULL CHECK (method IN ('cash','bank_transfer','ewallet','qris','other')),
  amount         INTEGER NOT NULL CHECK (amount > 0),
  tendered_amount INTEGER NOT NULL DEFAULT 0 CHECK (tendered_amount >= 0),
  change_amount  INTEGER NOT NULL DEFAULT 0 CHECK (change_amount >= 0),
  reference_no   TEXT,
  provider       TEXT,
  status         TEXT NOT NULL DEFAULT 'settled'
                   CHECK (status IN ('settled','pending','failed','voided')),
  paid_at        TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  received_by    TEXT NOT NULL,
  note           TEXT,
  created_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (sale_id) REFERENCES sales(id) ON DELETE CASCADE,
  FOREIGN KEY (shift_id) REFERENCES shifts(id) ON DELETE RESTRICT,
  FOREIGN KEY (received_by) REFERENCES users(id) ON DELETE RESTRICT,
  CHECK (tendered_amount = 0 OR tendered_amount >= amount),
  CHECK (change_amount = 0 OR method = 'cash')
) STRICT;

CREATE TABLE IF NOT EXISTS sale_returns (
  id            TEXT PRIMARY KEY,
  store_id      TEXT NOT NULL,
  sale_id       TEXT NOT NULL,
  return_no     TEXT NOT NULL,
  business_date TEXT NOT NULL,
  reason_code   TEXT NOT NULL CHECK (reason_code IN (
                  'damaged','expired','wrong_item','changed_mind','other')),
  reason        TEXT,
  refund_method TEXT NOT NULL DEFAULT 'original'
                  CHECK (refund_method IN ('original','cash','bank_transfer','ewallet','qris')),
  refund_amount INTEGER NOT NULL DEFAULT 0 CHECK (refund_amount >= 0),
  restock       INTEGER NOT NULL DEFAULT 1 CHECK (restock IN (0,1)),
  status        TEXT NOT NULL DEFAULT 'posted' CHECK (status IN ('posted','voided')),
  processed_by  TEXT NOT NULL,
  shift_id      TEXT,
  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (sale_id) REFERENCES sales(id) ON DELETE RESTRICT,
  FOREIGN KEY (processed_by) REFERENCES users(id) ON DELETE RESTRICT,
  FOREIGN KEY (shift_id) REFERENCES shifts(id) ON DELETE RESTRICT,
  UNIQUE (store_id, return_no)
) STRICT;

CREATE TABLE IF NOT EXISTS sale_return_items (
  id                TEXT PRIMARY KEY,
  store_id          TEXT NOT NULL,
  return_id         TEXT NOT NULL,
  sale_item_id      TEXT NOT NULL,
  product_id        TEXT NOT NULL,
  variant_id        TEXT,
  unit_id           TEXT NOT NULL,
  qty               REAL NOT NULL CHECK (qty > 0),
  conversion_factor REAL NOT NULL CHECK (conversion_factor > 0),
  qty_base          REAL NOT NULL CHECK (qty_base > 0),
  unit_price        INTEGER NOT NULL DEFAULT 0 CHECK (unit_price >= 0),
  refund_amount     INTEGER NOT NULL DEFAULT 0 CHECK (refund_amount >= 0),
  restock           INTEGER NOT NULL DEFAULT 1 CHECK (restock IN (0,1)),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (return_id) REFERENCES sale_returns(id) ON DELETE CASCADE,
  FOREIGN KEY (sale_item_id) REFERENCES sale_items(id) ON DELETE RESTRICT,
  FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE RESTRICT,
  FOREIGN KEY (variant_id) REFERENCES product_variants(id) ON DELETE RESTRICT,
  FOREIGN KEY (unit_id) REFERENCES units(id) ON DELETE RESTRICT
) STRICT;

CREATE TABLE IF NOT EXISTS sale_voids (
  id          TEXT PRIMARY KEY,
  store_id    TEXT NOT NULL,
  sale_id     TEXT NOT NULL,
  reason      TEXT NOT NULL,
  voided_by   TEXT NOT NULL,
  approved_by TEXT,
  shift_id    TEXT,
  created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (sale_id) REFERENCES sales(id) ON DELETE RESTRICT,
  FOREIGN KEY (voided_by) REFERENCES users(id) ON DELETE RESTRICT,
  FOREIGN KEY (approved_by) REFERENCES users(id) ON DELETE RESTRICT,
  FOREIGN KEY (shift_id) REFERENCES shifts(id) ON DELETE RESTRICT,
  UNIQUE (sale_id)
) STRICT;

-- -----------------------------------------------------------------------------
-- Sync bookkeeping (local only)
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS sync_outbox (
  id              INTEGER PRIMARY KEY AUTOINCREMENT,
  store_id        TEXT NOT NULL,
  op_id           TEXT NOT NULL UNIQUE,
  table_name      TEXT NOT NULL,
  row_id          TEXT NOT NULL,
  operation       TEXT NOT NULL CHECK (operation IN ('upsert','delete')),
  payload_json    TEXT NOT NULL CHECK (json_valid(payload_json)),
  base_updated_at TEXT,
  created_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  synced_at       TEXT,
  attempts        INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0),
  last_error      TEXT,
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE
) STRICT;

CREATE TABLE IF NOT EXISTS sync_state (
  key        TEXT PRIMARY KEY,
  value_json TEXT NOT NULL CHECK (json_valid(value_json)),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
) STRICT;

CREATE TABLE IF NOT EXISTS sync_conflicts (
  id           TEXT PRIMARY KEY,
  store_id     TEXT NOT NULL,
  table_name   TEXT NOT NULL,
  row_id       TEXT NOT NULL,
  local_json   TEXT NOT NULL CHECK (json_valid(local_json)),
  remote_json  TEXT NOT NULL CHECK (json_valid(remote_json)),
  status       TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','resolved','ignored')),
  resolution   TEXT CHECK (resolution IS NULL OR resolution IN ('local','cloud','merged')),
  resolved_by  TEXT,
  created_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  resolved_at  TEXT,
  FOREIGN KEY (store_id) REFERENCES stores(id) ON DELETE CASCADE,
  FOREIGN KEY (resolved_by) REFERENCES users(id) ON DELETE SET NULL
) STRICT;

