-- -----------------------------------------------------------------------------
-- Reporting views
-- -----------------------------------------------------------------------------
CREATE VIEW IF NOT EXISTS v_product_stock AS
SELECT
  p.store_id,
  p.id AS product_id,
  p.name,
  p.sku,
  p.category_id,
  c.name AS category_name,
  p.base_unit_id,
  u.code AS base_unit,
  p.track_stock,
  p.is_active,
  COALESCE(SUM(sl.qty_on_hand), 0) AS qty_on_hand,
  p.min_stock_qty,
  CASE WHEN p.track_stock = 1 AND p.is_active = 1
        AND COALESCE(SUM(sl.qty_on_hand), 0) <= p.min_stock_qty
       THEN 1 ELSE 0 END AS is_low_stock,
  CASE WHEN COALESCE(SUM(sl.qty_on_hand), 0) <> 0
       THEN SUM(sl.qty_on_hand * sl.avg_cost) / SUM(sl.qty_on_hand)
       ELSE COALESCE(MAX(sl.avg_cost), p.cost_price, 0) END AS avg_cost,
  ROUND(COALESCE(SUM(sl.qty_on_hand * sl.avg_cost), 0)) AS stock_value
FROM products p
LEFT JOIN categories c ON c.id = p.category_id
JOIN units u ON u.id = p.base_unit_id
LEFT JOIN stock_levels sl ON sl.product_id = p.id
WHERE p.deleted_at IS NULL
GROUP BY p.id;

CREATE VIEW IF NOT EXISTS v_low_stock AS
SELECT *
FROM v_product_stock
WHERE track_stock = 1
  AND is_active = 1
  AND qty_on_hand <= min_stock_qty;

CREATE VIEW IF NOT EXISTS v_expiring_batches AS
SELECT
  b.store_id,
  b.id AS batch_id,
  b.product_id,
  p.name AS product_name,
  b.variant_id,
  v.name AS variant_name,
  b.batch_no,
  b.expiry_date,
  CAST(julianday(b.expiry_date) - julianday('now') AS INTEGER) AS days_to_expiry,
  b.qty_remaining,
  b.unit_cost,
  ROUND(b.qty_remaining * b.unit_cost) AS stock_value
FROM stock_batches b
JOIN products p ON p.id = b.product_id
LEFT JOIN product_variants v ON v.id = b.variant_id
WHERE b.qty_remaining > 0
  AND b.expiry_date IS NOT NULL;

CREATE VIEW IF NOT EXISTS v_sale_profit AS
SELECT
  si.store_id,
  si.sale_id,
  s.business_date,
  si.product_id,
  si.variant_id,
  si.qty_base,
  si.line_total AS revenue,
  si.cost_total AS cogs,
  si.line_total - si.cost_total AS gross_profit,
  CASE WHEN si.line_total > 0
       THEN ROUND(100.0 * (si.line_total - si.cost_total) / si.line_total, 2)
       ELSE 0 END AS margin_pct
FROM sale_items si
JOIN sales s ON s.id = si.sale_id
WHERE s.status = 'completed';

CREATE VIEW IF NOT EXISTS v_daily_sales AS
SELECT
  store_id,
  business_date,
  SUM(CASE WHEN status = 'completed' THEN 1 ELSE 0 END) AS transactions,
  SUM(CASE WHEN status = 'voided' THEN 1 ELSE 0 END) AS voids,
  SUM(CASE WHEN status = 'completed' THEN grand_total ELSE 0 END) AS gross_sales,
  SUM(CASE WHEN status = 'completed' THEN cost_total ELSE 0 END) AS cogs,
  SUM(CASE WHEN status = 'completed' THEN grand_total - cost_total ELSE 0 END) AS gross_profit,
  SUM(CASE WHEN status = 'completed' THEN due_total ELSE 0 END) AS credit_sales
FROM sales
GROUP BY store_id, business_date;

CREATE VIEW IF NOT EXISTS v_customer_ar AS
WITH per_sale AS (
  SELECT
    l.store_id,
    l.customer_id,
    l.sale_id,
    SUM(l.amount) AS remaining,
    MAX(l.due_date) AS due_date
  FROM credit_ledger l
  WHERE l.sale_id IS NOT NULL
  GROUP BY l.store_id, l.customer_id, l.sale_id
)
SELECT
  c.store_id,
  c.id AS customer_id,
  c.name,
  c.phone,
  c.credit_limit,
  c.credit_balance,
  MAX(0, c.credit_limit - c.credit_balance) AS available_credit,
  COALESCE(SUM(CASE WHEN ps.remaining > 0 THEN ps.remaining ELSE 0 END), 0) AS open_invoice_amount,
  COALESCE(SUM(CASE
    WHEN ps.remaining > 0 AND ps.due_date IS NOT NULL AND ps.due_date < date('now')
    THEN ps.remaining ELSE 0 END), 0) AS overdue_amount
FROM customers c
LEFT JOIN per_sale ps ON ps.customer_id = c.id AND ps.store_id = c.store_id
WHERE c.deleted_at IS NULL
GROUP BY c.id;

CREATE VIEW IF NOT EXISTS v_customer_aging AS
WITH per_sale AS (
  SELECT
    l.store_id,
    l.customer_id,
    l.sale_id,
    SUM(l.amount) AS remaining,
    MAX(l.due_date) AS due_date
  FROM credit_ledger l
  WHERE l.sale_id IS NOT NULL
  GROUP BY l.store_id, l.customer_id, l.sale_id
)
SELECT
  c.store_id,
  c.id AS customer_id,
  c.name,
  c.credit_balance,
  COALESCE(SUM(CASE WHEN ps.remaining > 0 AND (ps.due_date IS NULL OR ps.due_date >= date('now'))
    THEN ps.remaining ELSE 0 END), 0) AS current_amount,
  COALESCE(SUM(CASE WHEN ps.remaining > 0 AND ps.due_date < date('now')
    AND julianday('now') - julianday(ps.due_date) <= 30
    THEN ps.remaining ELSE 0 END), 0) AS days_1_30,
  COALESCE(SUM(CASE WHEN ps.remaining > 0 AND ps.due_date < date('now')
    AND julianday('now') - julianday(ps.due_date) > 30
    AND julianday('now') - julianday(ps.due_date) <= 60
    THEN ps.remaining ELSE 0 END), 0) AS days_31_60,
  COALESCE(SUM(CASE WHEN ps.remaining > 0 AND ps.due_date < date('now')
    AND julianday('now') - julianday(ps.due_date) > 60
    AND julianday('now') - julianday(ps.due_date) <= 90
    THEN ps.remaining ELSE 0 END), 0) AS days_61_90,
  COALESCE(SUM(CASE WHEN ps.remaining > 0 AND ps.due_date < date('now')
    AND julianday('now') - julianday(ps.due_date) > 90
    THEN ps.remaining ELSE 0 END), 0) AS days_90_plus
FROM customers c
LEFT JOIN per_sale ps ON ps.customer_id = c.id AND ps.store_id = c.store_id
WHERE c.deleted_at IS NULL
GROUP BY c.id;

CREATE VIEW IF NOT EXISTS v_supplier_ap AS
SELECT
  s.store_id,
  s.id AS supplier_id,
  s.name,
  COALESCE(SUM(p.due_total), 0) AS total_due,
  COALESCE(SUM(CASE WHEN p.due_total > 0 AND p.due_date IS NOT NULL AND p.due_date < date('now')
    THEN p.due_total ELSE 0 END), 0) AS overdue_amount,
  MIN(CASE WHEN p.due_total > 0 THEN p.due_date END) AS next_due_date
FROM suppliers s
LEFT JOIN purchases p ON p.supplier_id = s.id AND p.status = 'posted'
WHERE s.deleted_at IS NULL
GROUP BY s.id;

CREATE VIEW IF NOT EXISTS v_shift_summary AS
SELECT
  sh.id AS shift_id,
  sh.store_id,
  sh.business_date,
  sh.status,
  sh.opening_cash,
  COALESCE(SUM(cm.amount), 0) AS cash_movements,
  sh.opening_cash + COALESCE(SUM(cm.amount), 0) AS computed_expected,
  sh.expected_cash,
  sh.counted_cash,
  sh.difference
FROM shifts sh
LEFT JOIN cash_movements cm ON cm.shift_id = sh.id
GROUP BY sh.id;

CREATE VIEW IF NOT EXISTS v_trial_balance AS
SELECT
  a.store_id,
  a.id AS account_id,
  a.code,
  a.name,
  a.type,
  a.normal_balance,
  COALESCE(SUM(jl.debit), 0) AS total_debit,
  COALESCE(SUM(jl.credit), 0) AS total_credit,
  COALESCE(SUM(jl.debit), 0) - COALESCE(SUM(jl.credit), 0) AS balance
FROM accounts a
LEFT JOIN (
  SELECT jl.*
  FROM journal_lines jl
  JOIN journal_entries je ON je.id = jl.journal_entry_id
  WHERE je.status = 'posted'
) jl ON jl.account_id = a.id
GROUP BY a.id;

CREATE VIEW IF NOT EXISTS v_purchase_price_history AS
SELECT
  pi.store_id,
  pi.product_id,
  pi.variant_id,
  p.supplier_id,
  p.invoice_date,
  pi.unit_id,
  pi.qty,
  pi.unit_cost,
  pi.unit_cost_base,
  pi.batch_no,
  pi.expiry_date
FROM purchase_items pi
JOIN purchases p ON p.id = pi.purchase_id
WHERE p.status = 'posted';

CREATE VIEW IF NOT EXISTS v_inventory_valuation AS
SELECT
  sl.store_id,
  sl.product_id,
  sl.variant_id,
  p.name AS product_name,
  sl.qty_on_hand,
  sl.avg_cost,
  sl.last_cost,
  ROUND(sl.qty_on_hand * sl.avg_cost) AS avg_value,
  ROUND(sl.qty_on_hand * sl.last_cost) AS last_value
FROM stock_levels sl
JOIN products p ON p.id = sl.product_id;

CREATE VIEW IF NOT EXISTS v_product_sales_rank AS
SELECT
  si.store_id,
  s.business_date,
  si.product_id,
  si.variant_id,
  p.name AS product_name,
  SUM(si.qty_base) AS units_sold,
  SUM(si.line_total) AS revenue,
  SUM(si.cost_total) AS cogs,
  SUM(si.line_total - si.cost_total) AS gross_profit
FROM sale_items si
JOIN sales s ON s.id = si.sale_id
JOIN products p ON p.id = si.product_id
WHERE s.status = 'completed'
GROUP BY si.store_id, s.business_date, si.product_id, si.variant_id;

CREATE VIEW IF NOT EXISTS v_cash_flow AS
SELECT
  store_id,
  business_date,
  type,
  SUM(amount) AS amount,
  COUNT(*) AS entries
FROM cash_movements
GROUP BY store_id, business_date, type;

